// UNSHIELDED-FORMAT TEST integration (build flag XMR20_PRIVATE_HOLDER_TEST=local): PUBLIC tokens by default, optional
// shielded transfers. Replaces private-format.js of the earlier candidates in this test build.
//
// Behaviour (DESIGN.txt 8): every asset shows a PUBLIC and a SHIELDED balance. Send offers "Public transfer" (1 transaction)
// or "Private transfer" (2 transactions, from the shielded balance). Shield (1 tx) and Unshield (1 tx per note) are explicit
// actions. Bridge works on the PUBLIC balance only; a shielded balance is never unshielded silently. Legacy lots migrate to
// PUBLIC notes. Before approval the review shows the exact transaction count and the sum of the quoted XMR fees for every
// carrier of the operation. Boundaries (shield/unshield) are explained: they publish the amount and link a public owner to a
// shielded event.
//
// Key boundaries (unchanged from the earlier candidates): token keys (shielded spend key AND public owner key, scheme
// XMR20-TKD1) are derived in the holder worker from the account's recovery phrase and never leave it; scanning is local;
// records are built, proved (Penumbra's published keys) and signed in the worker; carriers are built, signed, paid and
// published by this wallet directly to the node (no relay); pending operations live in the encrypted journal with
// LOOKUP-BEFORE-RETRY recovery; the viewing key is exported only on the explicit share action.
import {maxControl,fillMaximum,atomic,inputAmount} from './max-amount.js';
import {createPrivateJournal} from './private-journal.js';
import {xmr} from './holder-carrier.js';
import {Transaction} from '@solana/web3.js';
export const PRIVATE_FORMAT_ENDPOINT=typeof __XMR20_PRIVATE_ENDPOINT__!=='undefined'&&__XMR20_PRIVATE_ENDPOINT__?__XMR20_PRIVATE_ENDPOINT__:'http://127.0.0.1:8940';
const SCHEME='XMR20-TKD1';
const KIND_WORD={public:'Public transfer',private:'Private transfer',shield:'Shield',unshield:'Unshield',burn:'Bridge redemption (public burn)'};
// Reservations across ALL pending operations: token inputs (public note ids or shielded commitments) and native XMR inputs.
export function reservedTokens(acc,except=null){const out=new Set();for(const [id,p] of Object.entries(acc.pending||{})){if(id===except)continue;if(['selected','quoted','built','signed','broadcasting','uncertain','published','partial','missing','mined'].includes(p.status))for(const c of p.reserved||[])out.add(c);}return out;}
// FIX (review M3): a carrier's outcome never ends the operation while another carrier of it is on chain. Rules:
//   ok        -> carrier published; operation 'published' when every carrier is published/mined, else 'partial'
//   uncertain -> carrier uncertain; operation 'partial' if any carrier is on chain, else 'uncertain'
//   conflict  -> carrier conflicted (its XMR input was spent elsewhere); operation 'partial' if any carrier is on chain, else 'conflicted'
//   refused   -> carrier refused; operation 'partial' if any carrier is on chain, else 'refused'
// Token reservations are held for 'partial' (reservedTokens above) until canonical completion, a proven conflicting token spend
// (reconcile -> rejected) or an explicit abandonment, which canAbandon() allows ONLY when no carrier is on chain or in flight.
const ON_CHAIN=['published','mined'],IN_FLIGHT=['broadcasting','uncertain'];
export function carrierOutcomeTransition(q,i,pub){const c=q.carriers?.[i]||{};q.carriers=q.carriers||[];
 const onChain=()=>q.carriers.some((x,k)=>x&&k!==i&&ON_CHAIN.includes(x.status));
 if(pub.ok){q.carriers[i]={...c,status:'published',recovered:Boolean(c.recovered||pub.recovered),resends:(c.resends||0)+(pub.resends||0)};q.recovered=Boolean(q.recovered||pub.recovered);q.error=undefined;q.status=q.carriers.every(x=>x&&ON_CHAIN.includes(x.status))?'published':'partial';return q;}
 if(pub.uncertain){q.carriers[i]={...c,status:'uncertain'};q.status=onChain()?'partial':'uncertain';q.error=`Broadcast outcome UNKNOWN for carrier ${i+1}: the node did not answer and does not report it yet. Nothing is re-sent blindly; the node is asked again on the next refresh.`;return q;}
 if(pub.doubleSpend){q.carriers[i]={...c,status:'conflicted'};q.status=onChain()?'partial':'conflicted';q.error=`Carrier ${i+1}’s XMR input was spent by another transaction; the record is still unpublished${onChain()?' while the other carrier IS on chain — the operation stays reserved':''}. Approve a new carrier (a new fee) from the pending list.`;return q;}
 q.carriers[i]={...c,status:'refused'};q.status=onChain()?'partial':'refused';q.error=`The node refused carrier ${i+1}: ${pub.reason||pub.status}. It was not re-sent${onChain()?'; the other carrier IS on chain, so the operation stays reserved':''}. Approve a new carrier from the pending list, or wait if the reason is temporary.`;return q;}
export function canAbandon(p){if(!p||!['refused','conflicted','built','signed'].includes(p.status))return false;return !(p.carriers||[]).some(c=>c&&(ON_CHAIN.includes(c.status)||IN_FLIGHT.includes(c.status)));}
export function needsCarrier(p){return Boolean(p?.wires?.length)&&(['built','conflicted','refused'].includes(p.status)||(p.status==='partial'&&(p.carriers||[]).some(c=>c&&['conflicted','refused'].includes(c.status))));}
export function reservedNative(acc,except=null){const out=new Set();for(const [id,p] of Object.entries(acc.pending||{})){if(id===except)continue;if(['quoted','built','signed','broadcasting','uncertain','published','partial','missing','mined','conflicted','refused'].includes(p.status)){for(const k of p.nativeInputs||[])out.add(k);for(const c of p.carriers||[])if(c?.keyImage)out.add(c.keyImage);}}return out;}
export function createPrivateFormat({endpoint=PRIVATE_FORMAT_ENDPOINT,account,oneShot,workerClient,store,secret,show,on,run,toast,esc,amount,units,compactTokenBalance,importSol,render,same,$,close}){
 const journal=createPrivateJournal({store});
 let backend=null,holder=null,journalAcc=null,error='',loading=false,statusLine='',refreshQueued=false,holderAccount=null;
 const network=()=>backend?.network||'offline-fakechain';const isStagenet=()=>network()==='stagenet';const features=()=>backend?.features||{mine:true,fund:true,bridge:true,credit:false,faucet:false,view:true};const nodeWord=()=>isStagenet()?'stagenet node':'test daemon';
 const workers=new Map();
 const post=async(action,body)=>{const r=await fetch(endpoint+'/action/'+action,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(120000)});const v=await r.json().catch(()=>({error:'Unreadable reply'}));if(!r.ok)throw Error(v.error||'Test backend refused the request.');return v;};
 const accountId=()=>{const a=account();return a?('ext-'+a.id).replace(/[^A-Za-z0-9_-]/g,'').slice(0,64):null;};
 const progressEl=()=>$('#progress');const setProgress=t=>{const el=progressEl();if(el)el.textContent=t;};
 let lastStatus='',operationStatus=false;const setStatus=t=>{statusLine=t;const row=$('#pf-status');if(row)row.textContent=t;const el=progressEl();if(el&&(operationStatus||el.textContent===''||el.textContent===lastStatus))el.textContent=t;lastStatus=t;};
 const testHook=point=>{const h=globalThis.__pfTest;if(h?.crashAfter===point){delete h.crashAfter;throw Error('TEST HOOK: simulated interruption after '+point+' (the popup stopped here; nothing else ran).');}};
 async function ensureWorker(a){
  for(const [id,w] of workers)if(id!==a.id){w.client.close();workers.delete(id);}
  if(workers.has(a.id))return workers.get(a.id);
  const client=workerClient('private-holder.worker.js',{onProgress:p=>setStatus(p.text||'')});
  const w={client,tokenAddress:null,accountId:a.id};workers.set(a.id,w);
  try{const opened=await client.call('open',{seed:a.xmrSeed,owner:a.xmr,backend:endpoint,rpc:backend.rpcUrl},240000,{idle:true});Object.assign(w,{tokenAddress:opened.tokenAddress,shieldedAddress:opened.shieldedAddress,ownerKey:opened.ownerKey,nativeAddress:opened.nativeAddress,scheme:opened.scheme,engine:opened.engine,parameters:opened.parameters});return w;}
  catch(e){client.close();workers.delete(a.id);throw e;}}
 async function register(a,tokenAddress,w=null){if(isStagenet())return post('register',{id:accountId(),sol:a.sol,xmr:w?.nativeAddress||a.xmr,tokenAddress});const keys=await oneShot('private-claim.worker.js','public-keys',{seed:a.xmrSeed,owner:a.xmr});return post('register',{id:accountId(),sol:a.sol,xmr:a.xmr,A:keys.A,B:keys.B,tokenAddress});}
 const current=()=>{const a=account();return a&&workers.get(a.id)?.tokenAddress&&holderAccount===a.id?workers.get(a.id):null;};
 const need=()=>{const w=current();if(!w)throw Error('The token wallet is still opening. Wait for the balances to load and try again.');return w;};
 async function refresh(){const a=account();if(!a)return;if(!a.xmrSeed||!a.sol){error='This account needs both a Monero recovery phrase and a Solana key for the token test.';backend=holder=null;render();return;}
  if(loading){refreshQueued=true;return;}loading=true;error='';if(holderAccount!==a.id){holder=null;journalAcc=null;holderAccount=null;render();}
  try{const id=accountId();backend=await post('state',{id});const w=await ensureWorker(a);if(account()?.id!==a.id)return;
   if(!backend.registered){await register(a,w.tokenAddress,w);backend=await post('state',{id});}
   if(backend.tokenAddress&&backend.tokenAddress!==w.tokenAddress)throw Error('The test backend knows this install under a different token address.');
   if(!journal.unlocked)await journal.unlock(secret());
   const reserve=[...reservedNative(journal.account(await journal.read(),w.tokenAddress))];
   holder=await w.client.call('sync',{reserveKeyImages:reserve},600000,{idle:true});if(account()?.id!==a.id)return;
   await reconcile(w,holder);journalAcc=journal.account(await journal.read(),w.tokenAddress);holderAccount=a.id;setStatus('');}
  catch(e){if(account()?.id===a.id){error=e.message;holder=null;}}
  finally{loading=false;if(account()?.id===a.id)render();if(refreshQueued){refreshQueued=false;void refresh();}}}
 // Journal reconciliation against the LOCAL replica (every record of every carrier): settled operations move to history;
 // signed carriers absent from the chain are re-sent AS-IS after a lookup; stale operations whose inputs were spent elsewhere
 // are rejected without a fee; a rolled-back record returns its operation to the signed state (same carriers, no new fee).
 const spentTokens=status=>{const s=new Set((status.shielded?.spent||[]).map(n=>n.commitment));const live=new Set((status.public?.notes||[]).map(n=>n.id));return {s,live};};
 async function reconcile(w,status){const conf=backend.confirmations;const now=Date.now();const republish=[],claimQueue=[],release=[];const {s:spentShielded,live:livePublic}=spentTokens(status);
  await journal.write(j=>{const acc=journal.account(j,w.tokenAddress);
   for(const hpast of acc.history.slice()){if((hpast.status==='confirmed'||hpast.status==='mined')&&hpast.recordIds?.length&&hpast.recordIds.some(r=>!status.records[r])&&hpast.carriers?.some(c=>c?.blob)&&hpast.id&&!acc.pending[hpast.id]){acc.history=acc.history.filter(x=>x!==hpast);const {settled,...entry}=hpast;acc.pending[hpast.id]={...entry,status:'signed',heartbeat:0,error:'The chain rolled back below this operation; the same carrier(s) are re-sent (no new fee).',rolledBack:(entry.rolledBack||0)+1};}}
   for(const [id,p] of Object.entries(acc.pending)){const recs=(p.recordIds||[]).map(r=>status.records[r]||null);
    // Stale installation / stale backup: an input of a saved record was spent by another operation. Never send it: reject, release the XMR input(s), no fee.
    const inputsGone=(p.reserved||[]).some(c=>p.inputKind==='public'?(!livePublic.has(c)&&!recs.some(Boolean)):spentShielded.has(c));
    if(recs.every(r=>!r)&&inputsGone&&['built','signed','published','partial','missing','conflicted'].includes(p.status)){p.status='rejected';p.error='Inputs already spent by another installation (or an earlier operation); this saved operation was NOT sent and no carrier fee was paid'+(p.carriers?.some(Boolean)?' (signed carrier(s) discarded)':'')+'.';acc.history.unshift({...p,id,settled:now});acc.history=acc.history.slice(0,30);delete acc.pending[id];for(const k of p.nativeInputs||[])release.push(k);continue;}
    if(recs.length&&recs.every(Boolean)){const anyRejected=recs.some(r=>r.status==='rejected');const allAccepted=recs.every(r=>r.status==='accepted');p.txids=recs.map(r=>r.txid);p.height=Math.max(...recs.map(r=>r.height));p.confirmations=Math.min(...recs.map(r=>r.confirmations));
     if(anyRejected){p.status='rejected';p.error=recs.find(r=>r.status==='rejected').error;}else if(allAccepted){p.status=p.confirmations>=conf?'confirmed':'mined';}else{p.status='partial';p.error=undefined;}
     if(p.status==='confirmed'||p.status==='rejected'){acc.history.unshift({...p,id,settled:now});acc.history=acc.history.slice(0,30);delete acc.pending[id];if(p.status==='rejected')for(const c of p.carriers||[])if(c?.keyImage)release.push(c.keyImage);}continue;}
    const live=now-(p.heartbeat||p.created)<20000;
    if(p.status==='selected'||p.status==='quoted'){if(!live){for(const k of p.nativeInputs||[])release.push(k);delete acc.pending[id];}continue;}
    if(live&&(p.status==='built'||p.status==='signed'))continue;
    // Some carriers are not on chain: re-send those (lookup first), one by one.
    if(['signed','broadcasting','uncertain','missing','partial'].includes(p.status)||(p.status==='published'&&status.tip-(p.publishedAtTip??status.tip)>=2)){(p.carriers||[]).forEach((c,i)=>{if(c?.blob&&!recs[i]&&!['refused','conflicted'].includes(c.status))republish.push([id,i]);});}}
   for(const [claim,c] of Object.entries(acc.claims))if(c.phase==='signed')claimQueue.push(claim);});
  if(release.length)await w.client.call('nativeRelease',{keyImages:release},30000).catch(()=>{});
  for(const [id,i] of republish){const acc=journal.account(await journal.read(),w.tokenAddress);const p=acc.pending[id];const c=p?.carriers?.[i];if(!c?.blob)continue;const txid=c.txid;
   setProgress(`Reconciling: asking the ${nodeWord()} whether carrier ${txid.slice(0,16)}… is already known (nothing is re-sent blindly)…`);
   let look=null;try{look=await w.client.call('carrierLookup',{txid},60000);}
   catch(e){await journal.write(j=>{const q=journal.account(j,w.tokenAddress).pending[id];if(q){if(q.status!=='signed')q.status='uncertain';q.error='The node could not be reached to check this carrier ('+e.message+'); it is checked again on the next refresh.';}});continue;}
   if(look.known){await journal.write(j=>{const q=journal.account(j,w.tokenAddress).pending[id];if(!q)return;q.carriers[i]={...q.carriers[i],status:look.inPool?'published':'mined'};Object.assign(q,{status:q.carriers.every(x=>['published','mined'].includes(x?.status))?'published':'partial',publishedAtTip:status.tip,recovered:true,error:undefined});});continue;}
   // Positively unknown. Is the saved record still admissible (or a pending half)? Never send a stale carrier.
   const v=await w.client.call('verify',p.wires.length>1?{wires:p.wires}:{wire:p.wires[0]},60000).catch(()=>null);
   if(v&&v.record==='rejected'){await journal.write(j=>{const a2=journal.account(j,w.tokenAddress);const q=a2.pending[id];if(!q)return;q.status='rejected';q.error='The node does not hold this carrier and the saved record no longer passes local admission (its inputs were spent elsewhere): the stale carrier was NOT sent and no fee was paid.';a2.history.unshift({...q,id,settled:Date.now()});a2.history=a2.history.slice(0,30);delete a2.pending[id];});for(const cc of p.carriers||[])if(cc?.keyImage)await w.client.call('nativeRelease',{keyImages:[cc.keyImage]},30000).catch(()=>{});continue;}
   setProgress(`Reconciling: the ${nodeWord()} does not know signed carrier ${i+1} of ${p.carriers.length}; re-sending the SAME transaction (no new fee)…`);
   await journal.write(j=>{const q=journal.account(j,w.tokenAddress).pending[id];if(q){q.status='broadcasting';q.carriers[i]={...q.carriers[i],status:'broadcasting'};}});
   try{const r=await w.client.call('carrierPublishRecover',{blob:c.blob,txid},240000);await applyPublishOutcome(w,id,i,r,status.tip);}
   catch(e){await journal.write(j=>{const q=journal.account(j,w.tokenAddress).pending[id];if(q){q.status='uncertain';q.error='Broadcast outcome unknown: '+e.message+'. Checked against the node on the next refresh.';}});}}
  for(const claim of claimQueue){const acc=journal.account(await journal.read(),w.tokenAddress);const c=acc.claims[claim];setProgress('Reconciling: submitting a signed migration claim that was interrupted…');
   try{await post('claimSubmit',{id:accountId(),body:c.body,legacySignature:c.signature,symbol:c.symbol||'X'});await journal.write(j=>{journal.account(j,w.tokenAddress).claims[claim].phase='submitted';});}
   catch(e){if(/already/i.test(e.message))await journal.write(j=>{journal.account(j,w.tokenAddress).claims[claim]={...c,phase:'submitted',note:e.message};});else await journal.write(j=>{journal.account(j,w.tokenAddress).claims[claim].error=e.message;});}}}
 // Map one carrier's publish outcome onto the operation: all carriers published -> 'published'; some -> 'partial';
 // uncertain -> 'uncertain'; refused -> 'conflicted' (XMR input spent elsewhere) or 'refused'. The proved record(s) are kept.
 async function applyPublishOutcome(w,opId,i,pub,tip){await journal.write(j=>{const q=journal.account(j,w.tokenAddress).pending[opId];if(!q)return;carrierOutcomeTransition(q,i,pub);if(pub.ok)q.publishedAtTip=tip;});return pub;}
 // Explicit abandonment (M3): only when no carrier is on chain or in flight; releases the token and XMR reservations, keeps a history row.
 async function abandonPending(w,opId){const release=[];await journal.write(j=>{const acc=journal.account(j,w.tokenAddress);const p=acc.pending[opId];if(!p)throw Error('No such pending operation.');if(!canAbandon(p))throw Error('This operation cannot be abandoned: a carrier is on chain or in flight; it completes or is rejected by the chain.');for(const c of p.carriers||[])if(c?.keyImage)release.push(c.keyImage);for(const k of p.nativeInputs||[])release.push(k);acc.history.unshift({...p,id:opId,status:'abandoned',settled:Date.now()});acc.history=acc.history.slice(0,30);delete acc.pending[opId];});
  if(release.length)await w.client.call('nativeRelease',{keyImages:[...new Set(release)]},30000).catch(()=>{});}
 const assets=()=>backend?.assets??[];
 const pubOf=r=>holder?.public?.balances?.[r.asset]??'0';const shOf=r=>holder?.shielded?.balances?.[r.asset]??'0';
 const shieldedNotesOf=r=>(holder?.shielded?.notes??[]).filter(n=>n.asset===r.asset);const publicNotesOf=r=>(holder?.public?.notes??[]).filter(n=>n.asset===r.asset);
 const pendingOf=r=>Object.entries(journalAcc?.pending??{}).filter(([,p])=>p.asset===r.asset).map(([id,p])=>({id,...p}));
 const tokenAddress=()=>current()?.tokenAddress||holder?.tokenAddress||'';
 const native=()=>holder?.native||null;
 const nativeLine=()=>{const n=native();if(!n)return 'XMR for carrier fees: unavailable';const spendable=n.outputs.filter(o=>!o.spent&&!o.reserved&&n.tip>=o.unlockedAt).length;const lockedAt=n.outputs.filter(o=>!o.spent&&!o.reserved&&n.tip<o.unlockedAt).map(o=>o.unlockedAt);return `XMR for carrier fees: ${xmr(n.unlocked)} XMR spendable in ${spendable} output${spendable===1?'':'s'}${BigInt(n.locked)>0n?` · ${xmr(n.locked)} XMR locked until block ${Math.max(...lockedAt)}`:''}${BigInt(n.reserved)>0n?` · ${xmr(n.reserved)} XMR reserved by pending carriers`:''}`;};
 const spendableOutputs=()=>{const n=native();return n?n.outputs.filter(o=>!o.spent&&!o.reserved&&n.tip>=o.unlockedAt).length:0;};
 function rowsHTML(){if(!accountId())return '';if(error)return `<div class="notice" id="pf-error-row">Token test unavailable: ${esc(error)}</div>`;if(!backend||!holder||holderAccount!==account()?.id)return `<div class="empty" id="pf-loading">Opening the token wallet… <span id="pf-status">${esc(statusLine)}</span></div>`;
  let html='';assets().forEach((r,i)=>{const pend=pendingOf(r);const total=(BigInt(pubOf(r))+BigInt(shOf(r))).toString();html+=`<button class="asset" id="asset-private-${i}"><span class="coin"><span class="coin-fallback">${esc(r.symbol)}</span></span><span class="asset-info"><strong>${esc(r.name)}</strong><small>Public ${esc(compactTokenBalance(pubOf(r)))} · Shielded ${esc(compactTokenBalance(shOf(r)))}${pend.length?' · '+pend.length+' pending':''}</small></span><span class="asset-amount"><strong title="${esc(amount(total))} ${esc(r.symbol)}">${esc(compactTokenBalance(total))} ${esc(r.symbol)}</strong><small class="asset-usd">${r.viewingKeyShared?'Viewing key shared':'Scanned locally'}</small></span></button>`;
   (r.legacy??[]).filter(l=>!l.claimed).forEach((l,j)=>{html+=`<button class="asset legacy-asset" id="asset-legacy-${i}-${j}"><span class="coin"><span class="coin-fallback">L</span></span><span class="asset-info"><strong>Legacy ${esc(r.symbol)} (not migrated)</strong><small>Previously bridged tokens · migrate to the new public format</small></span><span class="asset-amount"><strong title="${esc(amount(l.amount))} ${esc(r.symbol)}">${esc(compactTokenBalance(l.amount))} ${esc(r.symbol)}</strong><small class="asset-usd">Legacy</small></span></button>`;});});
  return html;}
 function bind(){assets().forEach((r,i)=>{on('asset-private-'+i,()=>detail(r));(r.legacy??[]).filter(l=>!l.claimed).forEach((l,j)=>on(`asset-legacy-${i}-${j}`,()=>legacyDetail(r,l)));});}
 const testNote=()=>`<p class="subtle">${isStagenet()?'STAGENET TEST WALLET — test funds only. ':'Synthetic test. '}Tokens are PUBLIC by default (amounts and owner keys visible on the test chain); shielding is your explicit choice. Token keys are derived in this extension from the account’s recovery phrase (scheme ${SCHEME}); the chain is scanned locally. Carrier transactions are built, signed and paid by this wallet with ${isStagenet()?'worthless stagenet':'test'} XMR and sent to the node directly; there is no relay. Shielded proofs use Penumbra’s published circuits and keys; this is experimental research, not an audited product. Nothing here touches real funds.</p>`;
 const paramsNote=()=>{const p=current()?.parameters;if(!p)return '';return `<p class="subtle" id="pf-params">Proving parameters: ${esc(p.label)}. Every parameter file is authenticated against the manifest shipped in this build (sha256 ${esc(p.manifestSha256.slice(0,16))}…${p.pinnedInBuild?', pinned in the worker':''}) before it is used.</p>`;};
 const statusWord=p=>({selected:'selecting inputs (nothing sent, no fee)',quoted:'fees quoted, awaiting approval (nothing sent)',built:'proved · needs carrier(s) (approve the fee to publish)',signed:'carrier(s) signed · not yet broadcast',broadcasting:'sending to the node · outcome not yet known',uncertain:'broadcast outcome UNKNOWN · the node is asked again on refresh (nothing re-sent blindly)',published:'published · in the node’s pool, waiting for a block',partial:`partially published · ${(p.carriers||[]).filter(c=>c&&['published','mined'].includes(c.status)).length} of ${(p.carriers||[]).length} carriers on their way; the rest is re-sent on refresh`,mined:`mined · ${p.confirmations||0} of ${backend?.confirmations} confirmations`,missing:'carrier not seen on chain yet (checked against the node on refresh)',conflicted:'a carrier conflicted · needs a new carrier',refused:'node refused a carrier · needs a new carrier',rejected:'rejected (nothing sent, no fee)',confirmed:`confirmed (${backend?.confirmations} confirmations)`}[p.status]||p.status);
 const feesOf=p=>(p.carriers||[]).filter(Boolean).reduce((n,c)=>n+BigInt(c.fee||0),0n);
 function pendingHTML(r){const pend=pendingOf(r);if(!pend.length)return '';return `<details open><summary>Pending operations (${pend.length})</summary>${pend.map(p=>`<p class="review-line"><span>${esc(KIND_WORD[p.kind]||p.kind)} ${esc(amount(p.amount))} ${esc(r.symbol)} · ${esc(p.transactions||1)} tx</span><strong>${esc(statusWord(p))}</strong></p>${(p.carriers||[]).filter(Boolean).map((c,i)=>`<p class="subtle">Carrier ${i+1}: ${esc(c.txid.slice(0,16))}… · fee ${esc(xmr(c.fee))} XMR · ${esc(c.nativeBytes)} bytes · ${esc(c.status||'')}</p>`).join('')}${p.recovered?'<p class="subtle">Recovered after a lost reply: the node already held a carrier; nothing was re-sent.</p>':''}${p.error?`<p class="error">${esc(p.error)}</p>`:''}${needsCarrier(p)?`<button class="text-btn wide" data-carry="${esc(p.id)}">Approve carrier fee(s) and publish the proved record(s)</button>`:''}${canAbandon(p)?`<button class="text-btn wide" data-abandon="${esc(p.id)}">Abandon this operation (releases its inputs; nothing is on chain)</button>`:''}`).join('')}<p class="subtle">Saved in the encrypted journal; checked against the chain on every refresh. After a lost reply the wallet asks the node first and re-sends the same signed transaction only if the node does not know it (no second carrier, no second fee). A private transfer completes only when BOTH of its carriers are on chain; a lone half changes nothing. Nothing is shown as confirmed before ${esc(backend?.confirmations)} confirmations.</p></details>`;}
 function historyHTML(r){const rows=(journalAcc?.history??[]).filter(h=>h.asset===r.asset).slice(0,6);if(!rows.length)return '';return `<details><summary>Recent operations (${rows.length})</summary>${rows.map(h=>`<p class="review-line"><span>${esc(KIND_WORD[h.kind]||h.kind)} ${esc(amount(h.amount))} ${esc(r.symbol)}</span><strong>${esc(statusWord(h))}</strong></p>${(h.carriers||[]).filter(Boolean).map(c=>`<p class="subtle">Carrier ${esc(c.txid)} · fee ${esc(xmr(c.fee))} XMR</p>`).join('')}${h.txids?.length?`<p class="subtle">Total fees ${esc(xmr(feesOf(h)))} XMR${h.height?` · block ${esc(h.height)}`:''}${h.recovered?' · recovered after a lost reply (nothing re-sent)':''}</p>`:''}${h.error?`<p class="subtle">${esc(h.error)}</p>`:''}`).join('')}</details>`;}
 function detail(r){const f=features();const shNotes=shieldedNotesOf(r),pubNotes=publicNotesOf(r);
  show(r.name,`<div class="monero-token-detail"><h1 class="page-title" title="${esc(amount(pubOf(r)))} public + ${esc(amount(shOf(r)))} shielded ${esc(r.symbol)}">${esc(compactTokenBalance(pubOf(r)))} ${esc(r.symbol)}</h1><p class="subtle">Public balance · ${pubNotes.length} note${pubNotes.length===1?'':'s'} (amounts and owner visible on chain)</p><h2 class="page-title" style="font-size:1.2em">${esc(compactTokenBalance(shOf(r)))} ${esc(r.symbol)} shielded</h2><p class="subtle">Shielded balance · ${shNotes.length} note${shNotes.length===1?'':'s'} · scanned locally to block ${esc(holder?.tip??'?')}${pendingOf(r).length?' · '+pendingOf(r).length+' pending':''}${isStagenet()?' · STAGENET (test funds only)':''}</p>${r.viewingKeyShared?'<p class="notice">Viewing key shared with the test indexer on your explicit request. It can see this asset’s shielded balance; it cannot spend.</p>':''}<label>Token address (receive ${esc(r.symbol)} publicly or privately)</label><div class="address" id="pf-token-address">${esc(tokenAddress())}</div>${isStagenet()?`<label>This account’s stagenet XMR address (carrier fees · worthless test coins)</label><div class="address" id="pf-native-address">${esc(current()?.nativeAddress||'')}</div>`:''}<p class="subtle" id="pf-native">${esc(nativeLine())}</p>${f.bridge?`<label>Solana test balance (${esc(r.symbol)} tokens)</label><div class="address">${esc(amount(r.solanaBalance))} ${esc(r.symbol)}</div>`:''}<button class="primary wide" id="pf-send">Send</button>${f.bridge?'<button class="secondary wide" id="pf-bridge">Bridge</button>':''}<button class="secondary wide" id="pf-shield">Shield (public → shielded, 1 transaction)</button><button class="secondary wide" id="pf-unshield">Unshield (shielded → public, 1 transaction per note)</button>${f.view!==false?'<button class="text-btn wide" id="pf-view">Share viewing key with the test indexer</button>':''}${f.fund?'<button class="text-btn wide" id="pf-fund">Mine test XMR to this account for carrier fees (test service)</button>':''}${f.mine?`<button class="text-btn wide" id="pf-mine">Advance test chain ${esc(backend.confirmations)} blocks (test service)</button>`:''}<p id="progress" class="busy" role="status"></p><div id="pf-review"></div>${pendingHTML(r)}${historyHTML(r)}${paramsNote()}${testNote()}</div>`);
  on('pf-send',()=>sendForm(r));if($('#pf-bridge'))on('pf-bridge',()=>bridgeForm(r));on('pf-shield',()=>shieldForm(r));on('pf-unshield',()=>unshieldForm(r));
  if($('#pf-view'))on('pf-view',()=>void run(async e=>{const w=need();setProgress('Exporting this wallet’s viewing key and sending it to the test indexer (explicit share)…');const vk=await w.client.call('viewingKey',{},30000);same(e);const v=await post('view',{id:accountId(),symbol:r.symbol,viewingKey:vk.viewingKey});same(e);setProgress(`Indexer view: ${amount(v.balance)} ${r.symbol} shielded, ${v.notes} note(s). It cannot spend and learns nothing about your public owner key.`);await refresh();}));
  if($('#pf-mine'))on('pf-mine',()=>void run(async e=>{setProgress('Mining test blocks…');const m=await post('mine',{blocks:backend.confirmations});same(e);await refresh();same(e);const next=assets().find(x=>x.symbol===r.symbol);setProgress(`Test chain at block ${m.tip}. Public ${amount(pubOf(next))} · shielded ${amount(shOf(next))} ${r.symbol}.`);}));
  if($('#pf-fund'))on('pf-fund',()=>void run(async e=>{setProgress('TEST SERVICE: mining coinbase rewards to this account’s Monero address (mature after 60 blocks)…');const f2=await post('fund',{id:accountId(),blocks:2});same(e);await refresh();same(e);setProgress(`Mined ${f2.funded} coinbase outputs to this account (test service). They unlock after 60 blocks; advance the chain. ${nativeLine()}`);}));
  document.querySelectorAll('[data-abandon]').forEach(b=>b.onclick=()=>void run(async e=>{const w=need();await abandonPending(w,b.dataset.abandon);same(e);setProgress('Operation abandoned; its token and XMR inputs are released. Nothing was on chain.');await refresh();}));
  document.querySelectorAll('[data-carry]').forEach(b=>b.onclick=()=>void run(async e=>{const w=need();const out=await carryPending(e,w,b.dataset.carry);same(e);setProgress(`Carrier(s) published for the saved record(s): ${out.carriers.map(c=>c.txid.slice(0,12)+'…').join(', ')}; fees ${xmr(out.total)} XMR paid from this wallet.`);await refresh();}));}
 // Fee approval for ONE operation with one or more carriers: exact per-carrier quotes, their total and the transaction count.
 function approveFees(quotes,plan,w,{kind}){return new Promise((resolve,reject)=>{const box=$('#pf-review');if(!box)return reject(Error('Review area missing'));const total=quotes.reduce((n,q)=>n+BigInt(q.fee),0n);
  box.innerHTML=`<p class="notice" id="pf-fee">${esc(KIND_WORD[kind]||kind)}: <strong>${quotes.length} Monero transaction${quotes.length===1?'':'s'}</strong>, total carrier fees <strong>${esc(xmr(total))} XMR</strong>.<br>${quotes.map((q,i)=>`Transaction ${i+1}: fee ${esc(xmr(q.fee))} XMR (${esc(q.weight)} weight bytes × ${esc(q.feePerWeight)} piconero; ${esc(plan.wireLengths[i])}-byte record, tx_extra ${esc(plan.extraBytes[i])} bytes), input ${esc(xmr(q.inputAmount))} XMR, change ${esc(xmr(q.changeAmount))} XMR back to you.`).join('<br>')}<br>Paid from this account’s own ${isStagenet()?'stagenet ':''}XMR${isStagenet()?' (worthless test coins)':' on the offline test chain'}. ${kind==='shield'||kind==='unshield'?'This boundary publishes the amount and links your public owner key to a shielded event. ':''}${kind==='private'?'Both transactions carry one shared operation id; the transfer completes only when both are on chain. ':''}Nothing has been proved or published yet.</p>`;
  setProgress(`${quotes.length} transaction${quotes.length===1?'':'s'}, ${xmr(total)} XMR in fees from this account’s XMR. Approve to prove and send, or cancel.`);
  const primary=document.querySelector('#modal button.primary.wide:not([hidden])');const anchor=primary&&primary.parentElement?primary:null;
  const approve=document.createElement('button');approve.className='primary wide';approve.id='pf-approve';approve.dataset.keep='1';approve.textContent=`Approve ${xmr(total)} XMR and send`;
  const cancel=document.createElement('button');cancel.className='secondary wide';cancel.id='pf-cancel';cancel.dataset.keep='1';cancel.textContent='Cancel';
  if(anchor){anchor.parentElement.insertBefore(approve,anchor);anchor.parentElement.insertBefore(cancel,anchor);anchor.hidden=true;}else{box.append(approve,cancel);}
  const done=()=>{approve.remove();cancel.remove();if(anchor)anchor.hidden=false;box.innerHTML='';};
  approve.onclick=()=>{done();resolve(true);};cancel.onclick=()=>{done();reject(Error('Cancelled before proving. Nothing was proved, reserved or published; the XMR input(s) were released.'));};});}
 // Shared operation core: select -> reserve in the journal -> PLAN the record sizes -> QUOTE one carrier per record (distinct XMR
 // inputs) -> approval of count + total -> prove (worker) -> persist records -> sign every carrier with its approved quote -> persist
 // -> publish each (lookup-first). Every step is journaled so an interruption resumes safely.
 async function operate(e,w,{kind,asset,symbol,amount:raw,to,binding,notes:preselected,inputKind}){
  const first=await journal.read();const acc0=journal.account(first,w.tokenAddress);const exclude=[...reservedTokens(acc0)];const excludeKi=[...reservedNative(acc0)];
  const sel=preselected?{notes:preselected}:inputKind==='public'?await w.client.call('selectPublic',{asset,amount:raw,exclude},30000):await w.client.call('select',{asset,amount:raw,exclude,max:kind==='unshield'?1:3},30000);same(e);
  const plan=await w.client.call('plan',{kind,inputs:sel.notes.length,change:true},30000);
  if(plan.transactions>spendableOutputs())throw Error(`This ${KIND_WORD[kind].toLowerCase()} needs ${plan.transactions} Monero transactions, each paid from a different spendable XMR output; this account has ${spendableOutputs()}. ${features().fund?'Mine test XMR to this account first.':'Receive XMR in separate outputs first.'}`);
  const opId=crypto.randomUUID();
  await journal.write(j=>{const acc=journal.account(j,w.tokenAddress);const taken=reservedTokens(acc);if(sel.notes.some(c=>taken.has(c)))throw Error('Those inputs were just reserved by another wallet window. Refresh and try again.');acc.pending[opId]={kind,inputKind,asset,symbol,amount:raw,to,binding,reserved:sel.notes,transactions:plan.transactions,plan,status:'selected',created:Date.now(),heartbeat:Date.now(),nativeInputs:[],carriers:[]};});
  const beat=setInterval(()=>{journal.write(j=>{const p=journal.account(j,w.tokenAddress).pending[opId];if(p&&['selected','quoted','built','signed'].includes(p.status))p.heartbeat=Date.now();}).catch(()=>{});},5000);
  let built=null;const quotes=[];
  try{
   operationStatus=true;
   for(let i=0;i<plan.transactions;i++){setProgress(`Quoting carrier fee ${i+1} of ${plan.transactions}: choosing an XMR input and sampling ring members in this wallet…`);const q=await w.client.call('carrierQuote',{kind,wireLen:plan.wireLengths[i],exclude:[...excludeKi,...quotes.map(x=>x.keyImage)]},120000);quotes.push(q);same(e);}
   operationStatus=false;
   await journal.write(j=>{const acc=journal.account(j,w.tokenAddress);const taken=reservedNative(acc);if(quotes.some(q=>taken.has(q.keyImage)))throw Error('An XMR input was just reserved by another wallet window. Refresh and try again.');const p=acc.pending[opId];if(!p)throw Error('Operation record vanished');Object.assign(p,{status:'quoted',nativeInputs:quotes.map(q=>q.keyImage),quotes:quotes.map(q=>({fee:q.fee,weight:q.weight,feePerWeight:q.feePerWeight,inputAmount:q.inputAmount})),heartbeat:Date.now()});});
   setProgress('');
   try{await approveFees(quotes,plan,w,{kind});}catch(err){for(const q of quotes)await w.client.call('carrierCancel',{quoteId:q.quoteId},30000).catch(()=>{});await journal.write(j=>{const acc=journal.account(j,w.tokenAddress);delete acc.pending[opId];});await w.client.call('nativeRelease',{keyImages:quotes.map(q=>q.keyImage)},30000).catch(()=>{});throw err;}
   same(e);testHook('approved');
   operationStatus=true;built=await w.client.call('build',{kind,asset,to,amount:raw,binding,notes:sel.notes},900000,{idle:true});operationStatus=false;same(e);
   const wires=built.wires||[built.wire],recordIds=built.recordIds||[built.recordId];
   await journal.write(j=>{const p=journal.account(j,w.tokenAddress).pending[opId];if(!p)throw Error('Operation record vanished');Object.assign(p,{status:'built',heartbeat:Date.now(),wires,recordIds,bytes:built.bytes,inputs:built.inputs,change:built.change,provingMs:built.provingMs,op:built.op});});
   testHook('built');
   setProgress(`Record${wires.length>1?'s':''} proved locally (${[].concat(built.bytes).join(' + ')} bytes, ${built.inputs} input${built.inputs===1?'':'s'}, ${Math.round(built.provingMs/1000)} s). Signing ${wires.length} carrier transaction${wires.length===1?'':'s'} in this wallet…`);
   const carriers=[];for(let i=0;i<wires.length;i++){const c=await w.client.call('carrierSign',{quoteId:quotes[i].quoteId,wire:wires[i]},120000);same(e);if(c.fee!==quotes[i].fee)throw Error('Carrier fee differs from the approved quote; not publishing.');carriers.push({txid:c.txid,blob:c.blob,fee:c.fee,keyImage:c.keyImage,nativeBytes:c.nativeBytes,extraBytes:c.extraBytes,signMs:c.signMs,status:'signed'});}
   await journal.write(j=>{const p=journal.account(j,w.tokenAddress).pending[opId];if(!p)throw Error('Operation record vanished');Object.assign(p,{status:'signed',heartbeat:Date.now(),carriers});});
   testHook('signed');
   const total=carriers.reduce((n,c)=>n+BigInt(c.fee),0n);setProgress(`${carriers.length} carrier${carriers.length===1?'':'s'} signed (fees ${xmr(total)} XMR). Sending to the ${nodeWord()}…`);
   let lastPub=null;for(let i=0;i<carriers.length;i++){
    await journal.write(j=>{const p=journal.account(j,w.tokenAddress).pending[opId];if(!p)throw Error('Operation record vanished');p.status='broadcasting';p.carriers[i].status='broadcasting';p.heartbeat=Date.now();});
    if(i===0)testHook('broadcasting');if(i===1)testHook('broadcasting-second');
    let pub;try{pub=await w.client.call('carrierPublishRecover',{blob:carriers[i].blob,txid:carriers[i].txid},240000);}
    catch(err){await journal.write(j=>{const p=journal.account(j,w.tokenAddress).pending[opId];if(p){p.status='uncertain';p.carriers[i].status='uncertain';p.error='Broadcast outcome unknown: '+err.message;}});
     throw Error(`Broadcast outcome UNKNOWN for carrier ${i+1}: the ${nodeWord()} did not answer and could not be asked whether it arrived (${err.message}). The signed carrier(s) are saved in the encrypted journal; on the next refresh the wallet asks the node first and re-sends the same transaction(s) only if unknown. No second fee, nothing lost.`);}
    same(e);lastPub=await applyPublishOutcome(w,opId,i,pub,holder?.tip??0);
    if(!pub.ok){if(pub.uncertain)throw Error(`Broadcast outcome UNKNOWN for carrier ${i+1} after ${pub.trail?.length||0} attempts. Nothing was re-sent blindly; refresh to check again (the same signed carrier is kept).`);
     throw Error(`The ${nodeWord()} refused carrier ${i+1} (${pub.reason}). ${pub.doubleSpend?'Its XMR input was spent by another transaction; approve a new carrier from the pending list (new fee; the proved record is kept).':'It stays saved as refused; approve a new carrier from the pending list.'}`);}}
   return {...built,wires,recordIds,carriers,quotes,opId,total,recovered:Boolean(lastPub?.recovered),resends:lastPub?.resends||0};}
  catch(err){if(!built){try{await journal.write(j=>{const acc=journal.account(j,w.tokenAddress);const p=acc.pending[opId];if(p&&(p.status==='selected'||p.status==='quoted'))delete acc.pending[opId];});}catch{}
    if(quotes.length&&!/Cancelled/.test(err.message)){for(const q of quotes)await w.client.call('carrierCancel',{quoteId:q.quoteId},30000).catch(()=>{});await w.client.call('nativeRelease',{keyImages:quotes.map(q=>q.keyImage)},30000).catch(()=>{});}}throw err;}
  finally{operationStatus=false;clearInterval(beat);}}
 // Proved record(s) saved without (valid) carriers: quote the missing carriers, approve, sign, publish. Records are not rebuilt.
 async function carryPending(e,w,opId){const acc=journal.account(await journal.read(),w.tokenAddress);const p=acc.pending[opId];if(!p?.wires?.length)throw Error('No saved record for this operation.');
  const missing=p.wires.map((_,i)=>i).filter(i=>!p.carriers?.[i]||['conflicted','refused'].includes(p.carriers[i].status));if(!missing.length)throw Error('Every carrier of this operation is already on its way.');
  const excludeKi=[...reservedNative(acc,opId)];const quotes=[];operationStatus=true;
  for(const i of missing){setProgress(`Quoting a carrier for saved record ${i+1} of ${p.wires.length}…`);quotes.push(await w.client.call('carrierQuote',{kind:p.kind,wireLen:p.wires[i].length/2,exclude:[...excludeKi,...quotes.map(q=>q.keyImage)]},120000));same(e);}
  operationStatus=false;setProgress('');
  try{await approveFees(quotes,{wireLengths:missing.map(i=>p.wires[i].length/2),extraBytes:missing.map(i=>p.plan?.extraBytes?.[i]??'?')},w,{kind:p.kind});}catch(err){for(const q of quotes)await w.client.call('carrierCancel',{quoteId:q.quoteId},30000).catch(()=>{});await w.client.call('nativeRelease',{keyImages:quotes.map(q=>q.keyImage)},30000).catch(()=>{});throw err;}
  same(e);const signed=[];
  for(let k=0;k<missing.length;k++){const i=missing[k];let c;try{c=await w.client.call('carrierSign',{quoteId:quotes[k].quoteId,wire:p.wires[i]},120000);}
   catch(err){if(/fails local admission/.test(err.message)){for(const q of quotes)await w.client.call('carrierCancel',{quoteId:q.quoteId},30000).catch(()=>{});await w.client.call('nativeRelease',{keyImages:quotes.map(q=>q.keyImage)},30000).catch(()=>{});await journal.write(j=>{const a2=journal.account(j,w.tokenAddress);const q=a2.pending[opId];if(q){q.status='rejected';q.error='This saved record is no longer valid on the chain (its inputs were spent elsewhere); no carrier was built and no fee was paid.';a2.history.unshift({...q,id:opId,settled:Date.now()});delete a2.pending[opId];}});throw Error('The saved record is no longer valid: its inputs were spent by another operation or installation. Nothing was sent and no fee was paid.');}throw err;}
   signed.push([i,{txid:c.txid,blob:c.blob,fee:c.fee,keyImage:c.keyImage,nativeBytes:c.nativeBytes,extraBytes:c.extraBytes,status:'signed'}]);}
  await journal.write(j=>{const q=journal.account(j,w.tokenAddress).pending[opId];if(!q)throw Error('Operation record vanished');q.carriers=q.carriers||[];for(const [i,c] of signed)q.carriers[i]=c;q.nativeInputs=q.carriers.filter(Boolean).map(c=>c.keyImage);q.status='signed';q.error=undefined;q.heartbeat=Date.now();});
  const out=[];let total=0n;for(const [i,c] of signed){await journal.write(j=>{const q=journal.account(j,w.tokenAddress).pending[opId];if(q){q.status='broadcasting';q.carriers[i].status='broadcasting';}});
   let pub;try{pub=await w.client.call('carrierPublishRecover',{blob:c.blob,txid:c.txid},240000);}catch(err){await journal.write(j=>{const q=journal.account(j,w.tokenAddress).pending[opId];if(q){q.status='uncertain';q.carriers[i].status='uncertain';q.error='Broadcast outcome unknown: '+err.message;}});throw Error('Broadcast outcome UNKNOWN ('+err.message+'). The signed carrier is saved; refresh asks the node first and re-sends the same transaction only if unknown.');}
   same(e);await applyPublishOutcome(w,opId,i,pub,holder?.tip??0);if(!pub.ok)throw Error(pub.uncertain?'Broadcast outcome UNKNOWN; nothing was re-sent blindly. Refresh to check again.':'The '+nodeWord()+' refused the carrier ('+pub.reason+'). It stays saved as '+(pub.doubleSpend?'conflicted':'refused')+'.');out.push(c);total+=BigInt(c.fee);}
  return {carriers:out,total};}
 const addrOk=s=>/^xmr20t1[a-z0-9]{20,}$/.test(s)||/^penumbra1[a-z0-9]{20,}$/.test(s);
 function sendForm(r,mode='public'){const pub=mode==='public';show('Send '+r.symbol,`<p class="subtle">${pub?'Public transfer: ONE Monero transaction; the amount and both owner keys are visible on the test chain. Spends your public balance.':'Private transfer: TWO Monero transactions carrying one shielded operation; amounts and the recipient stay hidden inside the shielded pool. Spends your shielded balance (shield first if needed).'} Exact change returns to you.</p><label>Mode</label><select id="pf-mode"><option value="public" ${pub?'selected':''}>Public transfer — 1 transaction</option><option value="private" ${pub?'':'selected'}>Private transfer — 2 transactions</option></select><label for="pf-to">Recipient token address (xmr20t1… or penumbra1…)</label><input id="pf-to" autocomplete="off" spellcheck="false">${maxControl('pf-amount','Amount ('+r.symbol+')')}<input id="pf-amount" inputmode="decimal" placeholder="0" autocomplete="off"><p class="subtle">Available ${pub?'publicly':'shielded'}: ${esc(amount(pub?pubOf(r):shOf(r)))} ${esc(r.symbol)} · ${pub?'up to four public notes per transfer':'up to three shielded notes per transfer'} · no token fee. ${pub?'':'Shielded: '+esc(amount(shOf(r)))+' · public: '+esc(amount(pubOf(r)))+' (use Shield to move public tokens into the shielded balance first; that is one more transaction and one more fee). '}The record(s) travel in ordinary Monero transaction(s) built and signed by this wallet; the XMR fees are paid from this account (${esc(nativeLine().replace('XMR for carrier fees: ',''))}) and shown for approval before anything is proved.</p><div id="pf-review"></div><button class="primary wide" id="pf-send-go">Send</button><button class="secondary wide" id="pf-back" data-keep>Back</button><p id="progress" class="busy" role="status"></p>`);
  $('#pf-mode').onchange=ev=>{const to=$('#pf-to').value;sendForm(r,ev.target.value);$('#pf-to').value=to;};$('#pf-amount-max').onclick=()=>void fillMaximum($('#pf-amount'),async()=>pub?pubOf(r):shOf(r));on('pf-back',()=>detail(r));
  on('pf-send-go',()=>void run(async e=>{const w=need();const to=$('#pf-to').value.trim(),raw=units($('#pf-amount').value.trim(),r.decimals??6).toString();if(!addrOk(to))throw Error('Enter the recipient’s token address (xmr20t1… or penumbra1…).');if(atomic(raw)<=0n)throw Error('Enter an amount.');
   if(pub){if(!to.startsWith('xmr20t1'))throw Error('A public transfer needs the recipient’s unified address (xmr20t1…); a penumbra1… address can only receive private transfers.');if(atomic(raw)>atomic(pubOf(r)))throw Error('Insufficient public balance.'+(atomic(raw)<=atomic(pubOf(r))+atomic(shOf(r))?' Your shielded balance covers it: unshield first, or choose a private transfer.':''));}
   else if(atomic(raw)>atomic(shOf(r)))throw Error('Insufficient shielded balance.'+(atomic(raw)<=atomic(pubOf(r))?' Your public balance covers it: Shield first (1 transaction), then send privately (2 transactions) — 3 transactions and three fees in total.':''));
   setProgress('Selecting inputs and reserving them in the encrypted journal…');const out=await operate(e,w,{kind:pub?'public':'private',inputKind:pub?'public':'shielded',asset:r.asset,symbol:r.symbol,amount:raw,to});same(e);
   setProgress(`${pub?'Public':'Private'} transfer published: ${out.transactions} transaction${out.transactions===1?'':'s'} (${out.carriers.map(c=>c.txid.slice(0,12)+'…').join(', ')}), fees ${xmr(out.total)} XMR paid from this wallet; change ${amount(out.change)} ${r.symbol}; proved locally in ${Math.round(out.provingMs/1000)} s.${out.recovered?' The node’s reply was lost but it already held a carrier: nothing was re-sent.':''} ${isStagenet()?`Confirmed after ${backend.confirmations} stagenet blocks; refresh later.`:'Advance the chain to confirm.'}`);await refresh();}));}
 function shieldForm(r){show('Shield '+r.symbol,`<p class="subtle">Move tokens from your PUBLIC balance into your SHIELDED balance. One Monero transaction. The shielded amount is published once at this boundary and your public owner key is linked to it; afterwards the tokens move privately.</p>${maxControl('pf-amount','Amount ('+r.symbol+')')}<input id="pf-amount" inputmode="decimal" placeholder="0" autocomplete="off"><p class="subtle">Available publicly: ${esc(amount(pubOf(r)))} ${esc(r.symbol)}. Proved in this extension with Penumbra’s published output key; the XMR fee is shown for approval first.</p><div id="pf-review"></div><button class="primary wide" id="pf-shield-go">Shield</button><button class="secondary wide" id="pf-back" data-keep>Back</button><p id="progress" class="busy" role="status"></p>`);
  $('#pf-amount-max').onclick=()=>void fillMaximum($('#pf-amount'),async()=>pubOf(r));on('pf-back',()=>detail(r));
  on('pf-shield-go',()=>void run(async e=>{const w=need();const raw=units($('#pf-amount').value.trim(),r.decimals??6).toString();if(atomic(raw)<=0n)throw Error('Enter an amount.');if(atomic(raw)>atomic(pubOf(r)))throw Error('Insufficient public balance.');
   const out=await operate(e,w,{kind:'shield',inputKind:'public',asset:r.asset,symbol:r.symbol,amount:raw,to:''});same(e);setProgress(`Shielded ${amount(raw)} ${r.symbol} (1 transaction ${out.carriers[0].txid.slice(0,12)}…, fee ${xmr(out.total)} XMR; public change ${amount(out.change)} ${r.symbol}; proved in ${Math.round(out.provingMs/1000)} s). Advance the chain to confirm.`);await refresh();}));}
 function unshieldForm(r){const notes=shieldedNotesOf(r).slice().sort((x,y)=>(BigInt(y.amount)>BigInt(x.amount)?1:-1));const largest=notes[0]?.amount||'0';show('Unshield '+r.symbol,`<p class="subtle">Move tokens from your SHIELDED balance back to your PUBLIC balance. One Monero transaction spends ONE shielded note; the unshielded amount becomes public and is linked to your owner key; the rest of that note stays shielded as change.</p>${maxControl('pf-amount','Amount ('+r.symbol+')')}<input id="pf-amount" inputmode="decimal" placeholder="0" autocomplete="off"><p class="subtle">Shielded: ${esc(amount(shOf(r)))} ${esc(r.symbol)} in ${notes.length} note${notes.length===1?'':'s'}; the largest single note holds ${esc(amount(largest))} ${esc(r.symbol)} — one unshield can move at most that much (unshield twice, or consolidate privately, for more). Proved in this extension with Penumbra’s published spend and output keys; the XMR fee is shown for approval first.</p><div id="pf-review"></div><button class="primary wide" id="pf-unshield-go">Unshield</button><button class="secondary wide" id="pf-back" data-keep>Back</button><p id="progress" class="busy" role="status"></p>`);
  $('#pf-amount-max').onclick=()=>void fillMaximum($('#pf-amount'),async()=>largest);on('pf-back',()=>detail(r));
  on('pf-unshield-go',()=>void run(async e=>{const w=need();const raw=units($('#pf-amount').value.trim(),r.decimals??6).toString();if(atomic(raw)<=0n)throw Error('Enter an amount.');if(atomic(raw)>atomic(largest))throw Error(`One unshield spends one shielded note; your largest note holds ${amount(largest)} ${r.symbol}. Unshield in parts.`);
   const out=await operate(e,w,{kind:'unshield',inputKind:'shielded',asset:r.asset,symbol:r.symbol,amount:raw,to:''});same(e);setProgress(`Unshielded ${amount(raw)} ${r.symbol} to your public balance (1 transaction ${out.carriers[0].txid.slice(0,12)}…, fee ${xmr(out.total)} XMR; shielded change ${amount(out.change)} ${r.symbol}; proved in ${Math.round(out.provingMs/1000)} s). Advance the chain to confirm.`);await refresh();}));}
 function bridgeForm(r,direction='deposit'){const dep=direction==='deposit';show('Bridge '+r.symbol,`<p class="bridge-intro">Move ${esc(r.symbol)} between Solana and the test chain. Deposits arrive as PUBLIC tokens (shield them afterwards if you want). Redemptions burn PUBLIC tokens only.</p><label for="pf-direction">Direction</label><select id="pf-direction"><option value="deposit" ${dep?'selected':''}>Solana → public tokens (deposit)</option><option value="redeem" ${dep?'':'selected'}>Public tokens → Solana (redeem)</option></select>${maxControl('pf-amount','Amount ('+r.symbol+')')}<input id="pf-amount" inputmode="decimal" placeholder="0" autocomplete="off"><p class="subtle">${dep?`Available on Solana: ${esc(amount(r.solanaBalance))} ${esc(r.symbol)}. ${r.feeBps?`This mint’s ${(r.feeBps/100).toLocaleString(undefined,{maximumFractionDigits:2})}% token transfer fee is deducted once on deposit`:'This mint has no token transfer fee: the full amount is credited'}; you sign the deposit with this account’s Solana key. The credit is a PUBLIC note to your owner key.`:`Available publicly: ${esc(amount(pubOf(r)))} ${esc(r.symbol)}${atomic(shOf(r))>0n?` (plus ${esc(amount(shOf(r)))} shielded — the bridge never unshields for you; use Unshield first if you want to redeem those)`:''}. The burn is a public record carried by one Monero transaction this wallet pays for (fee shown for approval); the payout goes to your Solana address after ${esc(backend.confirmations)} confirmations; the token fee is deducted once at payout.`}</p><div id="pf-review"></div><button class="primary wide" id="pf-bridge-go">${dep?'Review and sign deposit':'Redeem to Solana'}</button><button class="secondary wide" id="pf-back" data-keep>Back</button><p id="progress" class="busy" role="status"></p><details><summary>Pending payouts (test operator)</summary>${(r.payouts??[]).map(p=>`<p>${esc(p.txid.slice(0,16))}… · ${esc(amount(p.amount))} · ${esc(p.status)} · ${esc(p.confirmations)} conf.</p>${p.status==='paid'?'':`<button class="text-btn wide" data-payout="${esc(p.txid)}">Request operator payout (test service)</button>`}`).join('')||'<p class="subtle">None.</p>'}</details>`);
  $('#pf-direction').onchange=ev=>{$('#pf-amount').value='';bridgeForm(r,ev.target.value);};$('#pf-amount-max').onclick=()=>void fillMaximum($('#pf-amount'),async()=>dep?r.solanaBalance:pubOf(r));on('pf-back',()=>detail(r));
  document.querySelectorAll('[data-payout]').forEach(b=>b.onclick=()=>void run(async e=>{setProgress('Asking the test operator to pay this burn…');const p=await post('payout',{symbol:r.symbol,txid:b.dataset.payout});same(e);const msg=p.status==='paid'?`Paid ${amount(p.net)} ${r.symbol} to your Solana address${p.repeated?' (already paid earlier; no second payout)':''}.`:'Payout status: '+p.status;setProgress(msg);await refresh();same(e);const next=assets().find(x=>x.symbol===r.symbol);if(next){bridgeForm(next,'redeem');setProgress(msg);}}));
  on('pf-bridge-go',()=>void run(async e=>{const w=need();const raw=units($('#pf-amount').value.trim(),r.decimals??6).toString();if(atomic(raw)<=0n)throw Error('Enter an amount.');
   if(dep){if(atomic(raw)>atomic(r.solanaBalance))throw Error('Insufficient Solana token balance.');setProgress('Preparing the deposit transaction…');const prep=await post('depositPrepare',{id:accountId(),symbol:r.symbol,amount:raw});same(e);
    const a=account();if(prep.review.owner!==a.sol||prep.review.mint!==r.mint||prep.review.gross!==raw||prep.review.creditTo!==w.tokenAddress)throw Error('Prepared deposit does not match this account.');const tx=Transaction.from(Uint8Array.from(atob(prep.transaction),c=>c.charCodeAt(0)));if(tx.instructions.length!==1||tx.feePayer?.toBase58()!==a.sol)throw Error('Unexpected deposit transaction.');
    setProgress(`Signing deposit of ${amount(prep.review.gross)} ${r.symbol} (fee ${amount(prep.review.fee)}, net ${amount(prep.review.net)}) with your Solana key…`);const key=importSol(a.solSecret);try{if(key.publicKey.toBase58()!==a.sol)throw Error('Selected Solana key differs.');tx.sign(key);}finally{key.secretKey.fill(0);}
    const d=await post('depositSubmit',{id:accountId(),nonce:prep.nonce,transaction:btoa(String.fromCharCode(...tx.serialize()))});same(e);setProgress(`Deposit accepted (net ${amount(d.receipt.net)} ${r.symbol}); PUBLIC credit ${d.credit.txid.slice(0,16)}… published to your owner key. Advance the chain ${backend.confirmations} blocks to see it.`);}
   else{if(atomic(raw)>atomic(pubOf(r)))throw Error('Insufficient PUBLIC balance.'+(atomic(shOf(r))>0n?' The bridge does not unshield for you: use Unshield first.':''));setProgress('Registering the redemption with the test operator…');const rp=await post('redeemPrepare',{id:accountId(),symbol:r.symbol,amount:raw});same(e);if(rp.destination!==account().sol)throw Error('Redemption destination is not this account’s Solana address.');
    const out=await operate(e,w,{kind:'burn',inputKind:'public',asset:r.asset,symbol:r.symbol,amount:raw,binding:rp.binding});same(e);setProgress(`Burn published (1 transaction ${out.carriers[0].txid.slice(0,12)}…, fee ${xmr(out.total)} XMR paid from this wallet; public change ${amount(out.change)} ${r.symbol}). Payout to your Solana address after ${backend.confirmations} confirmations.`);}
   await refresh();}));}
 function legacyDetail(r,l){show('Legacy '+r.symbol,`<div class="monero-token-detail"><h1 class="page-title" title="${esc(amount(l.amount))} ${esc(r.symbol)}">${esc(compactTokenBalance(l.amount))} ${esc(r.symbol)}</h1><p class="subtle">Legacy balance · not migrated</p><p class="notice">Previously bridged tokens stay legacy until you explicitly migrate them. Migration signs a one-time claim with this wallet’s own Monero keys for the legacy output shown below. No key image is revealed and nothing is spent on Monero. The credit is a PUBLIC note of exactly this amount to your owner key; shield it afterwards if you want.</p><label>Legacy output key</label><div class="address">${esc(l.P)}</div><button class="primary wide" id="pf-migrate">Migrate to the new format</button><button class="secondary wide" id="pf-back" data-keep>Back</button><p id="progress" class="busy" role="status"></p>${testNote()}</div>`);
  on('pf-back',close);
  on('pf-migrate',()=>void run(async e=>{const w=need();setProgress('Preparing the migration claim…');const prep=await post('claimPrepare',{id:accountId(),claim:l.claim,symbol:r.symbol});same(e);if(prep.body.owner!==w.tokenAddress||prep.body.amount!==l.amount||prep.P!==l.P)throw Error('Prepared claim does not match this legacy balance.');
   await journal.write(j=>{journal.account(j,w.tokenAddress).claims[l.claim]={phase:'prepared',symbol:r.symbol,asset:r.asset,body:prep.body,created:Date.now()};});testHook('claim-prepared');
   setProgress('Deriving the legacy output key from your Monero keys and signing locally…');const a=account();const sig=await oneShot('private-claim.worker.js','sign-claim',{seed:a.xmrSeed,owner:a.xmr,review:{messageHash:prep.messageHash,P:prep.P,txPublicKey:prep.txPublicKey,outputIndex:prep.outputIndex}});same(e);
   await journal.write(j=>{journal.account(j,w.tokenAddress).claims[l.claim]={phase:'signed',symbol:r.symbol,asset:r.asset,body:prep.body,signature:sig.signature,created:Date.now()};});testHook('claim-signed');
   setProgress('Submitting the signed claim…');const c=await post('claimSubmit',{id:accountId(),body:prep.body,legacySignature:sig.signature,symbol:r.symbol});same(e);await journal.write(j=>{journal.account(j,w.tokenAddress).claims[l.claim].phase='submitted';});
   setProgress(`Claim credited: ${c.txid.slice(0,16)}… for ${amount(c.amount)} ${r.symbol} as a PUBLIC note to your owner key. Advance the chain to see the balance.`);await refresh();}));}
 function reset(){for(const w of workers.values())w.client.close();workers.clear();journal.lock();backend=holder=journalAcc=null;holderAccount=null;error='';statusLine='';}
 globalThis.__pfDebug={state:async()=>({backend,holder,journal:journal.unlocked&&current()?journal.account(await journal.read(),current().tokenAddress):journalAcc,error,statusLine,parameters:current()?.parameters??null,nativeAddress:current()?.nativeAddress??null}),parameters:async()=>current()?current().client.call('parameters',{},30000):null};
 return {refresh,rowsHTML,bind,reset,get state(){return {backend,holder,journal:journalAcc};}};
}
